import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;

final class ClaimOffice {

    private static final ObjectMapper MAPPER = new ObjectMapper();
    private static final int PROCESSING_FEE = 5;
    private static final double FIRST_INSURANCE_SURCHARGE = 0.10;

    private ClaimOffice() {
    }

    static String run(String scenarioJson) {
        try {
            JsonNode scenario = MAPPER.readTree(scenarioJson);
            StringBuilder results = new StringBuilder();
            for (JsonNode step : scenario.get("steps")) {
                if (results.length() > 0) {
                    results.append(',');
                }
                results.append("{\"premium\":").append(quote(step)).append('}');
            }
            return "{\"results\":[" + results + "]}";
        } catch (com.fasterxml.jackson.core.JsonProcessingException e) {
            throw new IllegalArgumentException(e.getMessage(), e);
        }
    }

    private static long quote(JsonNode step) {
        double basePremium = 0;
        for (JsonNode item : step.get("items")) {
            basePremium += basePremiumOf(item);
        }
        double premium = basePremium + basePremium * FIRST_INSURANCE_SURCHARGE + PROCESSING_FEE;
        return (long) Math.ceil(premium);
    }

    private static double basePremiumOf(JsonNode item) {
        return 100;
    }
}
EOF
