  1	import com.fasterxml.jackson.databind.JsonNode;
  2	import com.fasterxml.jackson.databind.ObjectMapper;
  3	import java.util.LinkedHashMap;
  4	import java.util.Map;
  5	
  6	final class ClaimOffice {
  7	
  8	    private static final ObjectMapper MAPPER = new ObjectMapper();
  9	    private static final Map<String, Double> BASE_PREMIUMS = Map.of(
 10	            "sword", 100.0,
 11	            "amulet", 60.0,
 12	            "staff", 80.0,
 13	            "potion", 40.0,
 14	            "rune", 25.0,
 15	            "moonstone", 25.0);
 16	    private static final int PROCESSING_FEE = 5;
 17	    private static final int BLOCK_SIZE = 3;
 18	    private static final double BLOCK_BASE_PREMIUM = 60;
 19	    private static final double FIRST_INSURANCE_SURCHARGE = 0.10;
 20	    private static final double LOYALTY_DISCOUNT = 0.20;
 21	    private static final int LOYALTY_YEARS = 2;
 22	    private static final double FOLLOW_UP_DISCOUNT = 0.15;
 23	    private static final double CURSE_SURCHARGE = 0.50;
 24	    private static final double HIGH_ENCHANTMENT_SURCHARGE = 0.30;
 25	    private static final int HIGH_ENCHANTMENT_LEVEL = 5;
 26	
 27	    private ClaimOffice() {
 28	    }
 29	
 30	    static String run(String scenarioJson) {
 31	        try {
 32	            JsonNode scenario = MAPPER.readTree(scenarioJson);
 33	            JsonNode customer = scenario.get("customer");
 34	            StringBuilder results = new StringBuilder();
 35	            int contractsIssued = 0;
 36	            for (JsonNode step : scenario.get("steps")) {
 37	                if (results.length() > 0) {
 38	                    results.append(',');
 39	                }
 40	                results.append("{\"premium\":")
 41	                        .append(quote(step, customer, contractsIssued))
 42	                        .append('}');
 43	                contractsIssued++;
 44	            }
 45	            return "{\"results\":[" + results + "]}";
 46	        } catch (com.fasterxml.jackson.core.JsonProcessingException e) {
 47	            throw new IllegalArgumentException(e.getMessage(), e);
 48	        }
 49	    }
 50	
 51	    private static long quote(JsonNode step, JsonNode customer, int contractsIssued) {
 52	        JsonNode items = step.get("items");
 53	        double basePremium = policyBasePremium(items);
 54	        double itemSurcharges = 0;
 55	        for (JsonNode item : items) {
 56	            itemSurcharges += itemSurchargeOf(item);
 57	        }
 58	        double premium = basePremium + itemSurcharges
 59	                + basePremium * policyModifierRate(customer, contractsIssued)
 60	                + PROCESSING_FEE;
 61	        return (long) Math.ceil(premium);
 62	    }
 63	
 64	    private static double loyaltyDiscountRate(JsonNode customer) {
 65	        if (customer.get("yearsWithMHPCO").asInt() >= LOYALTY_YEARS) {
 66	            return LOYALTY_DISCOUNT;
 67	        }
 68	        return 0;
 69	    }
 70	
 71	    private static double policyModifierRate(JsonNode customer, int contractsIssued) {
 72	        return FIRST_INSURANCE_SURCHARGE
 73	                - loyaltyDiscountRate(customer)
 74	                - followUpDiscountRate(contractsIssued);
 75	    }
 76	
 77	    private static double followUpDiscountRate(int contractsIssued) {
 78	        if (contractsIssued > 0) {
 79	            return FOLLOW_UP_DISCOUNT;
 80	        }
 81	        return 0;
 82	    }
 83	
 84	    private static double policyBasePremium(JsonNode items) {
 85	        Map<String, Integer> countsByType = new LinkedHashMap<>();
 86	        for (JsonNode item : items) {
 87	            countsByType.merge(item.get("type").asText(), 1, Integer::sum);
 88	        }
 89	        double basePremium = 0;
 90	        for (Map.Entry<String, Integer> group : countsByType.entrySet()) {
 91	            basePremium += basePremiumOfGroup(group.getKey(), group.getValue());
 92	        }
 93	        return basePremium;
 94	    }
 95	
 96	    private static double itemSurchargeOf(JsonNode item) {
 97	        double listPremium = BASE_PREMIUMS.get(item.get("type").asText());
 98	        double surcharge = 0;
 99	        if (item.path("cursed").asBoolean()) {
100	            surcharge += listPremium * CURSE_SURCHARGE;
101	        }
102	        if (item.path("enchantment").asInt() >= HIGH_ENCHANTMENT_LEVEL) {
103	            surcharge += listPremium * HIGH_ENCHANTMENT_SURCHARGE;
104	        }
105	        return surcharge;
106	    }
107	
108	    private static double basePremiumOfGroup(String type, int count) {
109	        if (count == BLOCK_SIZE) {
110	            return BLOCK_BASE_PREMIUM;
111	        }
112	        return count * BASE_PREMIUMS.get(type);
113	    }
114	}

