1	import com.fasterxml.jackson.databind.JsonNode;
2	import com.fasterxml.jackson.databind.ObjectMapper;
3	import java.util.ArrayList;
4	import java.util.LinkedHashMap;
5	import java.util.List;
6	import java.util.Map;
7	
8	final class ClaimOffice {
9	
10	    private static final ObjectMapper MAPPER = new ObjectMapper();
11	    private static final Map<String, Double> INSURANCE_VALUES = Map.of(
12	            "sword", 1000.0,
13	            "amulet", 600.0,
14	            "staff", 800.0,
15	            "potion", 400.0,
16	            "rune", 250.0,
17	            "moonstone", 250.0);
18	    private static final Map<String, Double> BASE_PREMIUMS = Map.of(
19	            "sword", 100.0,
20	            "amulet", 60.0,
21	            "staff", 80.0,
22	            "potion", 40.0,
23	            "rune", 25.0,
24	            "moonstone", 25.0);
25	    private static final int PROCESSING_FEE = 5;
26	    private static final double DEDUCTIBLE = 100;
27	    private static final double CAP_FACTOR = 2;
28	    private static final int BLOCK_SIZE = 3;
29	    private static final double BLOCK_BASE_PREMIUM = 60;
30	    private static final double FIRST_INSURANCE_SURCHARGE = 0.10;
31	    private static final double LOYALTY_DISCOUNT = 0.20;
32	    private static final int LOYALTY_YEARS = 2;
33	    private static final double FOLLOW_UP_DISCOUNT = 0.15;
34	    private static final double CURSE_SURCHARGE = 0.50;
35	    private static final double HIGH_ENCHANTMENT_SURCHARGE = 0.30;
36	    private static final int HIGH_ENCHANTMENT_LEVEL = 5;
37	
38	    private ClaimOffice() {
39	    }
40	
41	    static String run(String scenarioJson) {
42	        try {
43	            JsonNode scenario = MAPPER.readTree(scenarioJson);
44	            JsonNode customer = scenario.get("customer");
45	            StringBuilder results = new StringBuilder();
46	            int contractsIssued = 0;
47	            List<Double> remainingCaps = new ArrayList<>();
48	            for (JsonNode step : scenario.get("steps")) {
49	                if (results.length() > 0) {
50	                    results.append(',');
51	                }
52	                if ("claim".equals(step.get("op").asText())) {
53	                    results.append(settle(step, remainingCaps));
54	                } else {
55	                    results.append("{\"premium\":")
56	                            .append(quote(step, customer, contractsIssued))
57	                            .append('}');
58	                    remainingCaps.add(CAP_FACTOR * insuranceSum(step.get("items")));
59	                    contractsIssued++;
60	                }
61	            }
62	            return "{\"results\":[" + results + "]}";
63	        } catch (com.fasterxml.jackson.core.JsonProcessingException e) {
64	            throw new IllegalArgumentException(e.getMessage(), e);
65	        }
66	    }
67	
68	    private static long quote(JsonNode step, JsonNode customer, int contractsIssued) {
69	        JsonNode items = step.get("items");
70	        double basePremium = policyBasePremium(items);
71	        double itemSurcharges = 0;
72	        for (JsonNode item : items) {
73	            itemSurcharges += itemSurchargeOf(item);
74	        }
75	        double premium = basePremium + itemSurcharges
76	                + basePremium * policyModifierRate(customer, contractsIssued)
77	                + PROCESSING_FEE;
78	        return (long) Math.ceil(premium);
79	    }
80	
81	    private static String settle(JsonNode step, List<Double> remainingCaps) {
82	        int policy = step.get("policy").asInt();
83	        double remainingCap = remainingCaps.get(policy);
84	        double payout = 0;
85	        for (JsonNode damage : step.get("incident").get("damages")) {
86	            payout += reimbursementFor(damage);
87	        }
88	        payout = Math.min(payout, remainingCap);
89	        remainingCaps.set(policy, remainingCap - payout);
90	        return "{\"payout\":" + (long) Math.floor(payout)
91	                + ",\"remainingCap\":" + (long) (remainingCap - payout) + "}";
92	    }
93	
94	    private static double reimbursementFor(JsonNode damage) {
95	        return damage.get("amount").asDouble() - DEDUCTIBLE;
96	    }
97	
98	    private static double insuranceSum(JsonNode items) {
99	        double sum = 0;
100	        for (JsonNode item : items) {
101	            sum += INSURANCE_VALUES.get(item.get("type").asText());
102	        }
103	        return sum;
104	    }
105	
106	    private static double loyaltyDiscountRate(JsonNode customer) {
107	        if (customer.get("yearsWithMHPCO").asInt() >= LOYALTY_YEARS) {
108	            return LOYALTY_DISCOUNT;
109	        }
110	        return 0;
111	    }
112	
113	    private static double policyModifierRate(JsonNode customer, int contractsIssued) {
114	        return FIRST_INSURANCE_SURCHARGE
115	                - loyaltyDiscountRate(customer)
116	                - followUpDiscountRate(contractsIssued);
117	    }
118	
119	    private static double followUpDiscountRate(int contractsIssued) {
120	        if (contractsIssued > 0) {
121	            return FOLLOW_UP_DISCOUNT;
122	        }
123	        return 0;
124	    }
125	
126	    private static double policyBasePremium(JsonNode items) {
127	        Map<String, Integer> countsByType = new LinkedHashMap<>();
128	        for (JsonNode item : items) {
129	            countsByType.merge(item.get("type").asText(), 1, Integer::sum);
130	        }
131	        double basePremium = 0;
132	        for (Map.Entry<String, Integer> group : countsByType.entrySet()) {
133	            basePremium += basePremiumOfGroup(group.getKey(), group.getValue());
134	        }
135	        return basePremium;
136	    }
137	
138	    private static double itemSurchargeOf(JsonNode item) {
139	        double listPremium = BASE_PREMIUMS.get(item.get("type").asText());
140	        double surcharge = 0;
141	        if (item.path("cursed").asBoolean()) {
142	            surcharge += listPremium * CURSE_SURCHARGE;
143	        }
144	        if (item.path("enchantment").asInt() >= HIGH_ENCHANTMENT_LEVEL) {
145	            surcharge += listPremium * HIGH_ENCHANTMENT_SURCHARGE;
146	        }
147	        return surcharge;
148	    }
149	
150	    private static double basePremiumOfGroup(String type, int count) {
151	        if (count == BLOCK_SIZE) {
152	            return BLOCK_BASE_PREMIUM;
153	        }
154	        return count * BASE_PREMIUMS.get(type);
155	    }
156	}

